#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<int> asteroidCollision(std::vector<int>& asteroids) {
        std::vector<int> st;
        for (int ast : asteroids) {
            bool destroyed = false;
            while (!st.empty() && ast < 0 && st.back() > 0) {
                if (st.back() < -ast) {
                    st.pop_back(); // Pop smaller right-moving asteroid
                    continue;
                } else if (st.back() == -ast) {
                    st.pop_back(); // Both explode
                }
                destroyed = true;
                break;
            }
            if (!destroyed) {
                st.push_back(ast);
            }
        }
        return st;
    }
};
